{
  "proposals": [
    {
      "id": "repair-sealed-warehouse-reachability",
      "title": "Add quarantine clearance producer for sealed warehouse",
      "summary": "Adds a reachable post-appointment quarantine decision that can set quarantineLifted. This supplies the missing tag required by sealed-warehouse without removing or loosening its requirements, while preserving the two-choice player loop and existing story state patterns.",
      "source": {
        "diagnostics": [
          "unreachable_cards",
          "unsatisfied_required_tags"
        ]
      },
      "target": {
        "cardIds": [
          "sealed-warehouse"
        ],
        "tags": [
          "quarantineLifted"
        ]
      },
      "patches": [
        {
          "op": "addCard",
          "card": {
            "id": "quarantine-clearance",
            "text": "检疫官送来最后一份报告：南码头连续七日没有新病例。码头上的人都在等你的旗号。",
            "weight": 1,
            "requirements": {
              "allTags": [
                "onWatch"
              ],
              "noneTags": [
                "quarantineLifted"
              ]
            },
            "choices": [
              {
                "id": "left",
                "label": "降旗解封",
                "effects": {
                  "factions": {
                    "gauge3": 4,
                    "gauge1": 6,
                    "gauge0": -3
                  },
                  "tags": {
                    "quarantineLifted": true
                  }
                }
              },
              {
                "id": "right",
                "label": "再封一天",
                "effects": {
                  "factions": {
                    "gauge1": -4,
                    "gauge0": 3,
                    "gauge3": -3
                  },
                  "tags": {
                    "shipsWaited": true
                  }
                }
              }
            ]
          }
        }
      ]
    }
  ]
}

